function applyLegacyAudits(nodes) {
  for (const replacement of auditedLegacyNodes) {
    const matches = nodes.map((node, i) => node.id === replacement.id ? i : -1).filter(i => i >= 0);
    if (matches.length !== 1) throw new Error('Legacy audit requires one matching ID: ' + replacement.id);
    nodes[matches[0]] = replacement;
  }
}

